/**
 * Realm spawn bands (pure). A side's zones and the roads out to them spawn by the campaign's quest order
 * (src/data/regions/hc/zoneBands.gen.ts, generated by tools/playthrough/bands.ts): each group has tiers that start
 * at the expected hero level of its first visit and step up once a later main quest's predecessor is done.
 * Groups the table doesn't know keep their old fixed band (`fallback`: zone 2 → L1, 3 → L5, 4 → L9; guards by kind).
 */
import { ZONE_BANDS, type ZoneTier } from '@/data/regions/hc/zoneBands.gen';

/** A level band that applies once `after` is completed (later tiers win). */
export interface LevelTier { after: string; level: [number, number]; elite?: boolean }
export interface Banded { level: [number, number]; elite?: boolean; tiers?: LevelTier[] }

/** patrols and camps lead elites only from this level (Claude 3: no elite walls below ~L8) */
const ELITE_FROM = 8;

/** The tiers of a group: the table's, or the old fixed floor. */
function groupTiers(group: string, fallback: number): ZoneTier[] {
  return ZONE_BANDS[group] ?? [{ floor: Math.max(1, fallback) }];
}

/** The zone-number floor (zone 2 → L1, 3 → L5, 4 → L9). */
export const zoneFloor = (zone: number): number => Math.max(1, 1 + (zone - 2) * 4);

/**
 * Level (and elite) of a spawn in `group` (zone n of a side, a realm's gate road, an optional area's approach),
 * from a tier's floor. `eliteGuard`: an approach guard that leads with an elite once its floor reaches L8.
 */
export function banded(group: string, fallback: number, kind: 'zone' | 'patrol' | 'camp-near' | 'camp' | 'guard', eliteGuard = false): Banded {
  const one = (f: number): { level: [number, number]; elite?: boolean } =>
    kind === 'zone' ? { level: [f, f + 2] }
      : kind === 'patrol' ? { level: [f + 1, f + 2], elite: f + 1 >= ELITE_FROM }
        : kind === 'camp-near' ? { level: [Math.max(1, f - 1), Math.max(1, f - 1) + 1] }
          : kind === 'guard' ? { level: [f, f + 1], elite: eliteGuard && f >= ELITE_FROM }
            : { level: [f, f + 1] };
  const [first, ...rest] = groupTiers(group, fallback);
  return { ...one(first.floor), tiers: rest.length ? rest.map((t) => ({ after: t.after!, ...one(t.floor) })) : undefined };
}

/** The level band in force for a spawn zone, given which quests are done. */
export function levelAt(z: Banded, done: (quest: string) => boolean): [number, number] {
  let lv = z.level;
  for (const t of z.tiers ?? []) if (done(t.after)) lv = t.level;
  return lv;
}

/** Whether a spawn zone leads with an elite, given which quests are done. */
export function eliteAt(z: Banded, done: (quest: string) => boolean): boolean {
  let e = !!z.elite;
  for (const t of z.tiers ?? []) if (done(t.after)) e = !!t.elite;
  return e;
}
